$positive_products$::JSONB) AS source(
    code TEXT, category_slug TEXT, file_stock INTEGER,
    file_name TEXT, file_price_minor BIGINT
);

ALTER TABLE recovery_positive_import ADD PRIMARY KEY(code);
ALTER TABLE recovery_positive_import ADD CHECK(file_stock > 0);

DO $validate_source$
BEGIN
    IF (SELECT COUNT(*) FROM recovery_positive_import) <> 659 THEN
        RAISE EXCEPTION 'positive-stock import must contain exactly 659 unique products';
    END IF;
    IF EXISTS (
        SELECT 1 FROM recovery_positive_import
        WHERE category_slug NOT IN ('plants','soil','fertilizer','pots','accessories')
    ) THEN
        RAISE EXCEPTION 'positive-stock import contains an unknown category';
    END IF;
END;
$validate_source$;

-- Keep the file self-contained. Normally every code is already in the Saby
-- directory; if a recently removed position is absent, preserve its stable
-- X-code and source data so the requested positive-stock card is not lost.
INSERT INTO saby_nomenclature(saby_id, code, name, price_minor, balance, seen_at)
SELECT source.code, source.code, source.file_name, source.file_price_minor,
       source.file_stock, CURRENT_TIMESTAMP
FROM recovery_positive_import source
WHERE NOT EXISTS (
    SELECT 1 FROM saby_nomenclature item
    WHERE UPPER(BTRIM(item.code)) = source.code
       OR UPPER(BTRIM(item.article)) = source.code
       OR UPPER(BTRIM(item.barcode)) = source.code
       OR UPPER(BTRIM(item.saby_id)) = source.code
)
ON CONFLICT(saby_id) DO NOTHING;

CREATE TEMP TABLE recovery_positive_candidates ON COMMIT DROP AS
SELECT DISTINCT ON (candidate.saby_id)
       requested.code, requested.category_slug, requested.file_stock,
       candidate.saby_id, COALESCE(NULLIF(candidate.name, ''), requested.file_name) AS name,
       candidate.description,
       CASE WHEN candidate.price_minor > 0 THEN candidate.price_minor ELSE requested.file_price_minor END AS price_minor,
       candidate.images
FROM recovery_positive_import requested
JOIN LATERAL (
    SELECT saby_id, name, description, price_minor, images
    FROM saby_nomenclature
    WHERE UPPER(BTRIM(code)) = requested.code
       OR UPPER(BTRIM(article)) = requested.code
       OR UPPER(BTRIM(barcode)) = requested.code
       OR UPPER(BTRIM(saby_id)) = requested.code
    ORDER BY (missing_since IS NULL) DESC, seen_at DESC, saby_id
    LIMIT 1
) candidate ON TRUE
WHERE NOT EXISTS (
    SELECT 1
    FROM products product
    LEFT JOIN saby_nomenclature linked ON linked.saby_id = product.saby_id
    WHERE product.saby_id = candidate.saby_id
       OR UPPER(BTRIM(linked.code)) = requested.code
       OR EXISTS (
           SELECT 1 FROM product_external_ids external
           WHERE external.product_id = product.id
             AND external.provider = 'saby'
             AND external.id_type = 'code'
             AND UPPER(BTRIM(external.external_id)) = requested.code
       )
)
ORDER BY candidate.saby_id, requested.code;

DO $import$
DECLARE
    item RECORD;
    category_id_value BIGINT;
    product_id_value BIGINT;
    variant_id_value BIGINT;
    slug_value TEXT;
BEGIN
    INSERT INTO warehouses(saby_id, name, city, address, is_active)
    VALUES ('saby-ryazan-main', 'Основной склад', 'Рязань', 'Новосёлов, 40А', 1)
    ON CONFLICT (saby_id) DO NOTHING;

    FOR item IN SELECT * FROM recovery_positive_candidates ORDER BY code LOOP
        SELECT id INTO STRICT category_id_value
        FROM categories WHERE slug = item.category_slug;

        slug_value := 'saby-' || LOWER(REGEXP_REPLACE(item.code, '[^A-Z0-9]+', '-', 'g'));
        IF EXISTS (SELECT 1 FROM products WHERE slug = slug_value) THEN
            slug_value := slug_value || '-' || SUBSTRING(MD5(item.saby_id), 1, 8);
        END IF;

        INSERT INTO products(
            saby_id, slug, name, latin_name, short_description, description,
            care_instructions, search_text, status, catalog_section, category_id,
            saby_fields, is_featured, updated_at
        ) VALUES (
            item.saby_id, slug_value, item.name, '', '', COALESCE(item.description, ''),
            '', item.name, 'draft', item.category_slug, category_id_value,
            ARRAY['stock']::TEXT[], 0, CURRENT_TIMESTAMP
        ) RETURNING id INTO product_id_value;

        INSERT INTO product_variants(
            product_id, saby_id, sku, label, base_price_minor, is_active, updated_at
        ) VALUES (
            product_id_value, item.saby_id, DEFAULT, 'Основной вариант',
            item.price_minor, 1, CURRENT_TIMESTAMP
        ) RETURNING id INTO variant_id_value;

        INSERT INTO product_external_ids(product_id, variant_id, provider, id_type, external_id)
        VALUES (product_id_value, variant_id_value, 'saby', 'id', item.saby_id)
        ON CONFLICT(provider, id_type, external_id) DO UPDATE SET
            product_id = EXCLUDED.product_id,
            variant_id = EXCLUDED.variant_id,
            updated_at = CURRENT_TIMESTAMP;

        INSERT INTO product_external_ids(product_id, variant_id, provider, id_type, external_id)
        VALUES (product_id_value, variant_id_value, 'saby', 'code', item.code)
        ON CONFLICT(provider, id_type, external_id) DO UPDATE SET
            product_id = EXCLUDED.product_id,
            variant_id = EXCLUDED.variant_id,
            updated_at = CURRENT_TIMESTAMP;

        INSERT INTO inventory(warehouse_id, variant_id, available_qty, reserved_qty, synced_at)
        SELECT id, variant_id_value, item.file_stock, 0, CURRENT_TIMESTAMP
        FROM warehouses WHERE saby_id = 'saby-ryazan-main'
        ON CONFLICT(warehouse_id, variant_id) DO UPDATE SET
            available_qty = EXCLUDED.available_qty,
            synced_at = CURRENT_TIMESTAMP;

        INSERT INTO product_media(product_id, object_key, alt_text, sort_order, is_primary)
        SELECT product_id_value, image, item.name, ordinal - 1,
               CASE WHEN ordinal = 1 THEN 1 ELSE 0 END
        FROM UNNEST(COALESCE(item.images, ARRAY[]::TEXT[])) WITH ORDINALITY AS media(image, ordinal)
        WHERE BTRIM(image) <> '';
    END LOOP;
END;
$import$;
